import { readFileSync } from "fs";
const rows = (f: string) => {
  const [h, ...r] = readFileSync(f, "utf8").trim().split("\n");
  const k = h.split(",");
  return r.map((l) => Object.fromEntries(l.split(",").map((v, i) => [k[i], v])));
};
const d = rows("data/deploys.csv"), inc = rows("data/incidents.csv");
const days = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const by: any = {};
for (const x of d) {
  const t = new Date(x.deployed_at);
  const k = days[t.getUTCDay()] + " " + (t.getUTCHours() < 12 ? "am" : "pm");
  by[k] ??= [0, 0]; by[k][0]++; if (x.incident_id) by[k][1]++;
}
console.log(by);
for (const x of d.filter((x) => x.incident_id)) {
  const t = new Date(x.deployed_at);
  const i = inc.find((i) => i.incident_id === x.incident_id)!;
  console.log(x.deploy_id, days[t.getUTCDay()], x.deployed_at,
    "lead h", ((+t - +new Date(x.committed_at)) / 36e5).toFixed(1),
    "to-inc h", ((+new Date(i.started_at) - +t) / 36e5).toFixed(1),
    "dur h", ((+new Date(i.resolved_at) - +new Date(i.started_at)) / 36e5).toFixed(1), i.summary);
}
const hrs = (x: any) => new Date(x.deployed_at).getUTCHours();
const am = d.filter((x) => hrs(x) < 12), pm = d.filter((x) => hrs(x) >= 12);
console.log("am", am.length, am.filter((x) => x.incident_id).length, "pm", pm.length, pm.filter((x) => x.incident_id).length);
console.log("hours", d.map(hrs).join(" "));
const lead = (x: any) => (+new Date(x.deployed_at) - +new Date(x.committed_at)) / 36e5;
const s = d.filter((x) => lead(x) < 24), l = d.filter((x) => lead(x) >= 24);
console.log("lead<24h", s.length, s.filter((x) => x.incident_id).length, ">=24h", l.length, l.filter((x) => x.incident_id).length);

